namespace Falcon.FSATS.ResourceManagement.Awareness;
public sealed record ResearchEgressBinding(string FoundationCandidate,string SourceAwarenessId,string SourceTier,string Purpose,string Destination,string RoutePolicyIdentity,string AuthorityEvidence,string EvidenceReference,bool RouteAuthorized,bool OperationalDataPurpose,bool BrokerExecutionPurpose,bool LiveAuthority,bool FsaDirectInternet,bool ConnectionExecuted); public sealed record ResearchEgressDecision(bool Accepted,string ReasonCode,bool ConnectionExecutionAuthorized,bool BusinessAuthorityGranted,bool LiveAuthorityGranted); public static class FoundationResearchEgressGovernance{public const string Stage12Candidate="3e5977da254894afb29f39302cd7791612e44178";public static ResearchEgressDecision Evaluate(ResearchEgressBinding? x){if(x is null||new[]{x.SourceAwarenessId,x.SourceTier,x.Purpose,x.Destination,x.RoutePolicyIdentity,x.AuthorityEvidence,x.EvidenceReference}.Any(string.IsNullOrWhiteSpace))return R("INCOMPLETE_RESEARCH_ROUTE_IDENTITY");if(!StringComparer.Ordinal.Equals(x.FoundationCandidate,Stage12Candidate))return R("FOUNDATION_STAGE12_CANDIDATE_MISMATCH");if(!StringComparer.Ordinal.Equals(x.Purpose,"RESEARCH_ONLY"))return R("PURPOSE_NOT_RESEARCH_ONLY");if(x.OperationalDataPurpose||x.BrokerExecutionPurpose||x.LiveAuthority||x.FsaDirectInternet)return R("RESEARCH_EGRESS_SCOPE_ESCALATION_REJECTED");if(x.ConnectionExecuted)return R("ROUTE_BINDING_DOES_NOT_EXECUTE_CONNECTION");if(!x.RouteAuthorized)return R("ROUTE_NOT_AUTHORIZED");return new(true,"RESEARCH_ROUTE_BINDING_ACCEPTED",false,false,false);}private static ResearchEgressDecision R(string r)=>new(false,r,false,false,false);}
